import base64
import tempfile
from pathlib import Path

SAMPLE_BASE64 = (
    ""
)


def sample_bytes() -> bytes:
    return base64.b64decode(SAMPLE_BASE64)


def write_sample_file() -> Path:
    data = sample_bytes()
    temp = tempfile.NamedTemporaryFile(delete=False)
    temp.write(data)
    temp.flush()
    temp.close()
    return Path(temp.name)
